--
-- Table structure for table `item_changes`
--

DROP TABLE IF EXISTS `item_changes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `item_changes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `version_item_id` bigint(20) unsigned NOT NULL,
  `changed_by` bigint(20) unsigned NOT NULL,
  `field_name` varchar(255) NOT NULL,
  `old_value` text DEFAULT NULL,
  `new_value` text DEFAULT NULL,
  `change_type` varchar(255) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `item_changes_version_item_id_index` (`version_item_id`),
  KEY `item_changes_changed_by_index` (`changed_by`),
  KEY `item_changes_created_at_index` (`created_at`),
  CONSTRAINT `item_changes_changed_by_foreign` FOREIGN KEY (`changed_by`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `item_changes_version_item_id_foreign` FOREIGN KEY (`version_item_id`) REFERENCES `version_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

