--
-- Table structure for table `test_runs`
--

DROP TABLE IF EXISTS `test_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `test_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `run_id` char(36) NOT NULL,
  `project_version_id` bigint(20) unsigned NOT NULL,
  `schema_version` varchar(10) NOT NULL DEFAULT '1.0',
  `base_url` varchar(2048) NOT NULL,
  `mode` varchar(50) NOT NULL DEFAULT 'agent',
  `status` enum('created','running','completed','failed') NOT NULL DEFAULT 'created',
  `requested_by` bigint(20) unsigned DEFAULT NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `finished_at` timestamp NULL DEFAULT NULL,
  `summary_total` int(10) unsigned NOT NULL DEFAULT 0,
  `summary_passed` int(10) unsigned NOT NULL DEFAULT 0,
  `summary_failed` int(10) unsigned NOT NULL DEFAULT 0,
  `summary_blocked` int(10) unsigned NOT NULL DEFAULT 0,
  `summary_skipped` int(10) unsigned NOT NULL DEFAULT 0,
  `request_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`request_payload`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `test_runs_run_id_unique` (`run_id`),
  KEY `test_runs_requested_by_foreign` (`requested_by`),
  KEY `test_runs_project_version_id_created_at_index` (`project_version_id`,`created_at`),
  KEY `test_runs_status_index` (`status`),
  CONSTRAINT `test_runs_project_version_id_foreign` FOREIGN KEY (`project_version_id`) REFERENCES `project_versions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `test_runs_requested_by_foreign` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=145 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

