INSERT INTO `user_stories` VALUES (1,1,'User can login with email and password','As a user, I want to login to the application using my email and password so that I can access my account.','Given I am on the login page\r\nWhen I enter a valid email and password\r\nThen I should be redirected to the dashboard\r\nAnd I should see a welcome message\r\nGiven I enter invalid credentials\r\nWhen I click login\r\nThen I should see an error message saying \"Invalid credentials\"','ready_for_test','critical',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(2,1,'User can create a new checklist','As a project manager, I want to create a new checklist so that I can organize my test items and share with team members.','Given I am on the checklists page\r\nWhen I click \"Create Checklist\"\r\nAnd I fill in the name and description\r\nAnd I click Save\r\nThen the checklist should appear in the list\r\nAnd I should be redirected to the checklist details page','in_progress','high',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(3,1,'User can add test items to a checklist','As a tester, I want to add individual test items to a checklist so that I can track test execution.','Given I am viewing a checklist\r\nWhen I click \"Add Item\"\r\nAnd I enter the item title and description\r\nAnd I select a criticality level\r\nAnd I click Save\r\nThen the item should appear in the checklist\r\nAnd the item should be unchecked by default\r\nAnd I should be able to add another item','in_progress','high',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(4,1,'User can mark test items as complete','As a tester, I want to mark test items as complete so that I can track my progress.','Given I am viewing a checklist with items\r\nWhen I click the checkbox next to an item\r\nThen the item should be marked as complete\r\nAnd the checklist progress should update\r\nAnd the completion percentage should show','backlog','high',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(5,1,'User can filter checklists by category','As a user, I want to filter checklists by category so that I can quickly find relevant checklists.','Given I am on the checklists page\r\nWhen I click the filter dropdown\r\nAnd I select a category\r\nThen only checklists from that category should display\r\nAnd the selected filter should be highlighted\r\nWhen I select \"All Categories\"\r\nThen all checklists should display again','backlog','medium',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(6,1,'User receives email notification when assigned to project','As a tester, I want to receive an email when I am assigned to a project so that I am informed immediately.','Given a user is assigned to a project\r\nWhen the assignment is saved\r\nThen an email should be sent to the user\r\nAnd the email should contain the project name\r\nAnd the email should include a link to the project\r\nAnd the email should be professional and clear','ready_for_test','medium',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(7,1,'User can export checklist as PDF','As a project manager, I want to export checklists as PDF so that I can share them offline and print them.','Given I am viewing a checklist\r\nWhen I click \"Export as PDF\"\r\nThen a PDF file should be generated\r\nAnd the PDF should include all checklist items with descriptions\r\nAnd the PDF should show the completed/incomplete status\r\nAnd the PDF should be downloaded to my computer','backlog','medium',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(8,1,'User can duplicate an existing checklist','As a user, I want to duplicate an existing checklist so that I can reuse templates for similar test scenarios.','Given I am viewing a checklist\r\nWhen I click \"Duplicate\"\r\nThen a copy of the checklist should be created\r\nAnd the copy should have the same items\r\nAnd the copy should have \"(Copy)\" in the name\r\nAnd I should be able to edit the duplicated checklist','backlog','low',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(9,1,'User can search for specific test items','As a user, I want to search for test items by keyword so that I can quickly find relevant tests.','Given I am viewing a checklist with multiple items\r\nWhen I type a keyword in the search box\r\nThen only items matching the keyword should display\r\nAnd the search should work across all field names and descriptions\r\nAnd search results should update in real-time','backlog','low',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(10,1,'User can set reminder for incomplete items','As a tester, I want to set reminders for incomplete test items so that I do not forget to complete them.','Given I am viewing an incomplete test item\r\nWhen I click \"Set Reminder\"\r\nAnd I select a date and time\r\nAnd I click Save\r\nThen I should receive a reminder at the specified time\r\nAnd the reminder should include the item details','backlog','low',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(11,1,'System generates test cases from user stories','As a developer, I want the system to automatically generate test cases from user story acceptance criteria so that I can save time on test planning.','Given I have a user story with acceptance criteria in Given-When-Then format\r\nWhen I click \"Generate Test Cases\"\r\nThen the system should parse the acceptance criteria\r\nAnd create individual test cases for each scenario\r\nAnd the test cases should appear in a new checklist\r\nAnd each test case should have appropriate criticality assigned','in_progress','critical',NULL,1,'2026-04-18 10:08:15','2026-04-18 10:08:15',NULL),(12,1,'User can login with email and password','As a user, I want to login to the application using my email and password so that I can access my account.','Given I am on the login page\r\nWhen I enter a valid email and password\r\nThen I should be redirected to the dashboard\r\nAnd I should see a welcome message\r\nGiven I enter invalid credentials\r\nWhen I click login\r\nThen I should see an error message saying \"Invalid credentials\"','ready_for_test','critical',NULL,1,'2026-04-18 10:15:48','2026-04-18 10:15:48',NULL),(13,1,'User can create a new checklist','As a project manager, I want to create a new checklist so that I can organize my test items and share with team members.','Given I am on the checklists page\r\nWhen I click \"Create Checklist\"\r\nAnd I fill in the name and description\r\nAnd I click Save\r\nThen the checklist should appear in the list\r\nAnd I should be redirected to the checklist details page','in_progress','high',NULL,1,'2026-04-18 10:15:48','2026-04-18 10:15:48',NULL),(14,1,'User can add test items to a checklist','As a tester, I want to add individual test items to a checklist so that I can track test execution.','Given I am viewing a checklist\r\nWhen I click \"Add Item\"\r\nAnd I enter the item title and description\r\nAnd I select a criticality level\r\nAnd I click Save\r\nThen the item should appear in the checklist\r\nAnd the item should be unchecked by default\r\nAnd I should be able to add another item','in_progress','high',NULL,1,'2026-04-18 10:15:48','2026-04-18 10:15:48',NULL),(15,1,'User can mark test items as complete','As a tester, I want to mark test items as complete so that I can track my progress.','Given I am viewing a checklist with items\r\nWhen I click the checkbox next to an item\r\nThen the item should be marked as complete\r\nAnd the checklist progress should update\r\nAnd the completion percentage should show','backlog','high',NULL,1,'2026-04-18 10:15:48','2026-04-18 10:15:48',NULL),(16,1,'User can filter checklists by category','As a user, I want to filter checklists by category so that I can quickly find relevant checklists.','Given I am on the checklists page\r\nWhen I click the filter dropdown\r\nAnd I select a category\r\nThen only checklists from that category should display\r\nAnd the selected filter should be highlighted\r\nWhen I select \"All Categories\